css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .8); display: flex; flex-direction: column; justify-content: space-between; padding: 7%; border-radius: 5px; background: #0b1220; box-shadow: inset 0 0 0 2px #24334d; }
.loader span { position: relative; height: 11%; border-radius: 2px; animation: diff-in calc(var(--loader-speed) * 2.8) ease-out infinite; }
.loader span:nth-child(odd) { background: var(--accent); }
.loader span:nth-child(even) { background: var(--accent-2); }
.loader span::before { content: ''; position: absolute; top: 22%; left: -6%; width: 3.5%; height: 56%; border-radius: 1px; background: rgba(255, 255, 255, .45); }
.loader span:nth-child(1) { --w: 84%; }
.loader span:nth-child(2) { --w: 62%; animation-delay: calc(var(--loader-speed) * .16); }
.loader span:nth-child(3) { --w: 94%; animation-delay: calc(var(--loader-speed) * .32); }
.loader span:nth-child(4) { --w: 48%; animation-delay: calc(var(--loader-speed) * .48); }
.loader span:nth-child(5) { --w: 76%; animation-delay: calc(var(--loader-speed) * .64); }
.loader span:nth-child(6) { --w: 58%; animation-delay: calc(var(--loader-speed) * .8); }
@keyframes diff-in { 0% { opacity: 0; width: 0; } 12% { opacity: 1; } 36% { width: var(--w); } 84% { width: var(--w); } 96%, 100% { opacity: 0; width: 0; } }
